# ---- text measuring ---------------------------------------------------------------
def text_width(text, size, tracking=0.0):
    """Approximate rendered width in px of `text` in Newsreader."""
    return sum(SERIF_ADV.get(ch, 0.45) for ch in text) * size + tracking * len(text)


def mono_width(text, size, spacing_em):
    """Rendered width in px of `text` in JetBrains Mono with letter-spacing."""
    return len(text) * size * (MONO_ADV + spacing_em)


def fit_line(line, size, max_w, tracking=0.0):
    """Ellipsize a line that is still too wide for max_w."""
    if text_width(line, size, tracking) <= max_w:
        return line
    line = line.rstrip(".,;: ")
    while line and text_width(line + "…", size, tracking) > max_w:
        line = line[:-1].rstrip(".,;: ")
    return line + "…"


def wrap_px(text, size, max_w, max_lines=2):
    """Greedy word wrap by rendered width; ellipsize if it runs past max_lines."""
    lines, cur = [], ""
    for word in text.split():
        trial = f"{cur} {word}".strip()
        if cur and text_width(trial, size) > max_w:
            lines.append(cur)
            cur = word
        else:
            cur = trial
    if cur:
        lines.append(cur)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        lines[-1] = lines[-1] + "…"
    return [fit_line(line, size, max_w) for line in lines] or [""]


def font_face_css():
    faces = [
        ("Newsreader", "normal", "400", FONT_B64["serif"]),
        ("Newsreader", "italic", "400", FONT_B64["serif_italic"]),
        ("JetBrains Mono", "normal", "100 800", FONT_B64["mono"]),
    ]
    return "\n".join(
        f"@font-face {{ font-family:'{fam}'; font-style:{style}; font-weight:{weight}; "
        f"src:url(data:font/woff2;base64,{data}) format('woff2'); }}"
        for fam, style, weight, data in faces
    )


# ---- data: GitHub, weather, status ------------------------------------------------
def is_excluded(repo_name):
    """True for the profile repo. Accepts 'name' or 'owner/name'."""
    return repo_name.split("/")[-1].lower() == EXCLUDED_REPO.lower()


def github_get(url):
    req = Request(
        url,
        headers={
            "Authorization": f"Bearer {TOKEN}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
        },
    )
    with urlopen(req, timeout=20) as response:
        return json.loads(response.read())


def github_graphql(query, variables):
    payload = json.dumps({"query": query, "variables": variables}).encode()
    req = Request(
        "https://api.github.com/graphql",
        data=payload,
        headers={
            "Authorization": f"Bearer {TOKEN}",
            "Content-Type": "application/json",
        },
    )
    with urlopen(req, timeout=20) as response:
        result = json.loads(response.read())
    if "errors" in result:
        raise RuntimeError(result["errors"])
    return result["data"]


# (from hour, to hour exclusive, status) in IST; covers all 24 hours, no overlaps.
STATUSES = [
    (0, 2, "having a chai without sugar"),
    (2, 6, "am I dreaming"),
    (6, 9, "at the gym"),
    (9, 12, "good morning, time to ship"),
    (12, 15, "biriyani time"),
    (15, 20, "debugging arc"),
    (20, 24, "struggling with a deadline"),
]


def get_status(hour):
    return next(text for lo, hi, text in STATUSES if lo <= hour < hi)


def get_weather():
    try:
        req = Request(
            "https://wttr.in/Hyderabad?format=j1",
            headers={"User-Agent": "README-refresh/1.0"},
        )
        with urlopen(req, timeout=15) as response:
            current = json.loads(response.read())["current_condition"][0]
        return {
            "location": "Hyderabad",
            "temperature": f"{current['temp_C']}°C",
            "condition": current["weatherDesc"][0]["value"].strip(),
        }
    except SOFT_ERRORS:
        return {"location": "Hyderabad", "temperature": None, "condition": "unavailable"}


def get_repositories():
    repos, page = [], 1
    while True:
        data = github_get(
            f"https://api.github.com/users/{USERNAME}/repos"
            f"?per_page=100&page={page}&type=owner&sort=pushed"
        )
        repos.extend(data)
        if len(data) < 100:
            break
        page += 1
    return [repo for repo in repos if not repo["fork"] and not repo["archived"]]


def get_languages(repos):
    """Top 5 languages by bytes, as (name, percent of all code)."""
    totals = Counter()
    for repo in repos:
        try:
            totals.update(github_get(repo["languages_url"]))
        except SOFT_ERRORS as e:
            print(f"Could not read languages for {repo['name']}: {e}")
    total = sum(totals.values()) or 1
    return [(lang, round(100 * size / total, 1)) for lang, size in totals.most_common(5)]


def get_latest_push(repos):
    """Most recent public push by the user, with its commit message.

    Uses the user's own push events, so commits made by the Actions bot
    (README refreshes) never count. The profile repo (EXCLUDED_REPO) is
    skipped entirely, both in events and in the fallback.
    Falls back to the most recently pushed other repo if events are unavailable.
    """
    try:
        events = github_get(
            f"https://api.github.com/users/{USERNAME}/events/public?per_page=100"
        )
        for event in events:
            if event.get("type") != "PushEvent":
                continue
            full_name = event["repo"]["name"]
            if is_excluded(full_name):
                continue

            name = full_name.split("/", 1)[-1]
            date, message = event["created_at"], None
            try:
                commit = github_get(
                    f"https://api.github.com/repos/{full_name}/commits/{event['payload']['head']}"
                )["commit"]
                message = commit["message"].strip().splitlines()[0]
                date = commit["author"]["date"]
            except SOFT_ERRORS as e:
                print(f"Could not read head commit of {full_name}: {e}")
            return name, date, message
    except SOFT_ERRORS as e:
        print(f"Could not read push events: {e}")

    candidates = [repo for repo in repos if not is_excluded(repo["name"])]
    if not candidates:
        return None, None, None
    latest = max(candidates, key=lambda repo: repo.get("pushed_at") or "")
    return latest["name"], latest.get("pushed_at"), None


def get_repo_stats(repos):
    """Total repo count, total stars, and the most-starred repo."""
    stars = sum(repo.get("stargazers_count", 0) for repo in repos)
    top = max(repos, key=lambda repo: repo.get("stargazers_count", 0), default=None)
    best = None
    if top and top.get("stargazers_count", 0) > 0:
        best = {"name": top["name"], "stars": top["stargazers_count"]}
    return {"total_repos": len(repos), "total_stars": stars, "most_starred_repo": best}


def get_activity():
    """Commits in the last 7 days (profile repo excluded), plus open issues and PRs."""
    since = (datetime.now(timezone.utc) - timedelta(days=7)).strftime("%Y-%m-%dT%H:%M:%SZ")
    query = """
    query($login: String!, $since: DateTime!) {
      user(login: $login) {
        contributionsCollection(from: $since) {
          commitContributionsByRepository(maxRepositories: 100) {
            repository { name owner { login } }
            contributions { totalCount }
          }
        }
        issues(states: OPEN) { totalCount }
        pullRequests(states: OPEN) { totalCount }
      }
    }
    """
    user = github_graphql(query, {"login": USERNAME, "since": since})["user"]
    commits = sum(
        entry["contributions"]["totalCount"]
        for entry in user["contributionsCollection"]["commitContributionsByRepository"]
        if not is_excluded(entry["repository"]["name"])
    )
    return commits, user["issues"]["totalCount"], user["pullRequests"]["totalCount"]


def get_contribution_stats():
    """Current streak, longest streak, and the last 30 days of daily counts.

    The contribution calendar can't be filtered per repo, so these include
    every repo GitHub credits to the account.
    """
    query = """
    query($login: String!) {
      user(login: $login) {
        contributionsCollection {
          contributionCalendar {
            weeks { contributionDays { date contributionCount } }
          }
        }
      }
    }
    """
    calendar = github_graphql(query, {"login": USERNAME})["user"][
        "contributionsCollection"
    ]["contributionCalendar"]
    days = sorted(
        (day for week in calendar["weeks"] for day in week["contributionDays"]),
        key=lambda day: day["date"],
    )
    counts = [day["contributionCount"] for day in days]

    longest = run = 0
    for count in counts:
        run = run + 1 if count > 0 else 0
        longest = max(longest, run)

    current = 0
    for count in reversed(counts):
        if count == 0:
            break
        current += 1

    return current, longest, counts[-30:]


def ago(iso):
    if not iso:
        return "unknown"
    delta = datetime.now(timezone.utc) - datetime.fromisoformat(iso.replace("Z", "+00:00"))
    minutes = int(delta.total_seconds() // 60)
    for unit, size in (("d", 1440), ("h", 60)):
        if minutes >= size:
            return f"{minutes // size}{unit} ago"
    return f"{max(minutes, 0)}m ago"


def fmt(value, suffix=""):
    return "n/a" if value is None else f"{value}{suffix}"


