# ---- SVG pieces -------------------------------------------------------------------
def render_status(status_raw):
    """Headline typed in letter by letter, then a blinking cursor."""
    status = status_raw[0].upper() + status_raw[1:].lower()
    size = 64
    while size > 34 and text_width(status, size, TRACK) > TYPE_MAX_W:
        size -= 1
    status = fit_line(status, size, TYPE_MAX_W, TRACK)
    n = len(status)

    # Cumulative x after each letter, so the cursor and the reveal edge land
    # exactly on letter boundaries (letters are not equal width).
    cum = [0.0]
    for ch in status:
        cum.append(cum[-1] + SERIF_ADV.get(ch, 0.45) * size + TRACK)
    cover_w = round(cum[-1] - TRACK + 2)

    delay = 0.7
    dur = round(n * 0.07, 2)
    after = round(delay + dur, 2)

    def frames(fn):
        return "".join(
            f"{i / n * 100:.3f}% {{ transform: {fn(i)}; animation-timing-function: step-end }}\n"
            for i in range(n + 1)
        )

    return {
        "STATUS": escape(status),
        "SIZE": str(size),
        "ORIGIN": str(58 + cover_w),
        "DUR": str(dur),
        "DELAY": str(delay),
        "AFTER": str(after),
        "REVEAL": frames(lambda i: f"scaleX({(cover_w - cum[i]) / cover_w:.4f})"),
        "SLIDE": frames(lambda i: f"translateX({cum[i]:.1f}px)"),
        "COVER_W": str(cover_w),
        "COVER_Y": str(BASE - 56),
        "CURSOR_Y": str(round(BASE - CAP_HEIGHT * size - 3)),
        "CURSOR_H": str(round(CAP_HEIGHT * size + 11)),
    }


def render_push(gh):
    """Latest repo name and its commit message, wrapped to three lines."""
    name = gh["latest_active_repo"] or "n/a"
    if len(name) > 40:
        name = name[:39] + "…"
    size = 34
    while size > 18 and text_width(name, size, -0.5) > RIGHT - COL:
        size -= 1

    message = gh.get("last_commit_message")
    if message:
        lines = wrap_px(message, 18, RIGHT - COL - 8, max_lines=3)
        lines[0], lines[-1] = "“" + lines[0], lines[-1] + "”"
    else:
        lines = ["no commit message"]
    msg = "".join(
        f'<text x="{COL}" y="{204 + i * 26}" class="msg">{escape(line)}</text>'
        for i, line in enumerate(lines)
    )
    return {
        "REPO": escape(name),
        "REPO_SIZE": str(size),
        "AGO": escape(ago(gh["last_commit"]).upper()),
        "MSG": msg,
    }


def render_cells(gh):
    stats = [
        (fmt(gh["total_repos"]), "REPOS"),
        (fmt(gh["total_stars"]), "STARS"),
        (fmt(gh.get("commits_last_7_days")), "COMMITS · 7D"),
        (fmt(gh.get("current_streak"), " d"), "STREAK"),
        (fmt(gh.get("longest_streak"), " d"), "BEST STREAK"),
        (fmt(gh.get("open_prs")), "OPEN PRS"),
    ]
    return "".join(
        f'<g class="in" style="--d:{1.25 + i * 0.1:.2f}s">'
        f'<text x="{LEFT + i * 140}" y="334" class="k">{escape(label)}</text>'
        f'<text x="{LEFT + i * 140}" y="382" class="num">{escape(value)}</text>'
        f"</g>"
        for i, (value, label) in enumerate(stats)
    )


def dune_path(pts):
    """Monotone cubic through pts (Fritsch–Carlson): smooth, and never dips
    below the data, so empty days stay on the baseline."""
    xs, ys = zip(*pts, strict=True)
    n = len(pts)
    slope = [(ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]) for i in range(n - 1)]
    tan = [slope[0]] + [
        0 if slope[i - 1] * slope[i] <= 0 else (slope[i - 1] + slope[i]) / 2
        for i in range(1, n - 1)
    ] + [slope[-1]]
    for i, s in enumerate(slope):
        if s == 0:
            tan[i] = tan[i + 1] = 0
            continue
        a, b = tan[i] / s, tan[i + 1] / s
        if a * a + b * b > 9:
            t = 3 / (a * a + b * b) ** 0.5
            tan[i], tan[i + 1] = t * a * s, t * b * s

    path = f"M{xs[0]:.1f},{ys[0]:.1f}"
    for i in range(n - 1):
        h = (xs[i + 1] - xs[i]) / 3
        path += (
            f" C{xs[i] + h:.1f},{ys[i] + tan[i] * h:.1f}"
            f" {xs[i + 1] - h:.1f},{ys[i + 1] - tan[i + 1] * h:.1f}"
            f" {xs[i + 1]:.1f},{ys[i + 1]:.1f}"
        )
    return path


def render_dune(daily):
    """Last 30 days of contributions as a sand dune, with ripples and a today marker."""
    daily = list(daily)[-30:]
    if not daily:
        flat = f"M{LEFT},{DUNE_Y} L{RIGHT},{DUNE_Y} L{RIGHT},{DUNE_Y} Z"
        line = f'<line x1="{LEFT}" y1="{DUNE_Y}" x2="{RIGHT}" y2="{DUNE_Y}" class="hair"/>'
        return {"DUNE": line, "DUNE_AREA": flat,
                "STRIP_LABEL": "ACTIVITY  ·  N/A", "STRIP_RIGHT": ""}
    if len(daily) == 1:
        daily = daily * 2

    peak = max(daily) or 1
    step = (RIGHT - LEFT) / (len(daily) - 1)
    pts = [(LEFT + i * step, DUNE_Y - 2 - (DUNE_H - 2) * c / peak) for i, c in enumerate(daily)]
    ridge = dune_path(pts)
    area = f"{ridge} L{RIGHT},{DUNE_Y} L{LEFT},{DUNE_Y} Z"

    # Wavy ripple lines, clipped to the dune and slowly pushed by the wind.
    wave = "q15,-3 30,0" + " t30,0" * 33
    ripples = "".join(
        f'<path class="ripple" d="M{LEFT - 60},{y} {wave}" fill="none" stroke-width="1"/>'
        for y in range(DUNE_Y - 8, DUNE_Y - DUNE_H, -9)
    )

    # Peak label (skipped when the peak is today, which gets its own marker).
    top = daily.index(max(daily))
    tx, ty = pts[-1]
    peak_label = ""
    if top != len(daily) - 1 and max(daily) > 0:
        px, py = pts[top]
        peak_label = (
            f'<line x1="{px:.1f}" y1="{py - 4:.1f}" x2="{px:.1f}" y2="{py - 12:.1f}" class="ink" stroke-width="1"/>'
            f'<text x="{px:.1f}" y="{py - 17:.1f}" class="k" text-anchor="middle">{max(daily)}</text>'
        )

    dune = (
        f'<g class="rise">'
        f'<path d="{area}" fill="url(#sand)"/>'
        f'<g clip-path="url(#duneclip)"><g class="wind">{ripples}</g></g>'
        f'<path d="{ridge}" fill="none" class="ink" stroke-width="1.5" stroke-linejoin="round"/>'
        f"</g>"
        f'<line x1="{LEFT}" y1="{DUNE_Y}" x2="{RIGHT}" y2="{DUNE_Y}" class="hair"/>'
        f'<g class="in" style="--d:3s">{peak_label}'
        f'<circle class="acc" cx="{tx:.1f}" cy="{ty:.1f}" r="4"/>'
        f'<circle class="acc pulse" cx="{tx:.1f}" cy="{ty:.1f}" r="4"/></g>'
    )
    return {
        "DUNE": dune,
        "DUNE_AREA": area,
        "STRIP_LABEL": f"LAST {len(daily)} DAYS  ·  {sum(daily)} CONTRIBUTIONS",
        "STRIP_RIGHT": f"TODAY {daily[-1]}  ·  PEAK {max(daily)}",
    }


def render_langs(share):
    """Language share as a thin segmented bar with labelled swatches below it."""
    if not share:
        return '<text x="60" y="598" class="mono">languages n/a</text>'

    # Leading language in the accent colour, the rest in fading ink.
    shades = [("acc", 1), ("inkf", .7), ("inkf", .45), ("inkf", .28), ("inkf", .16)]
    width = RIGHT - LEFT
    bar, labels = "", ""
    x, lx = LEFT, LEFT
    for (name, pct), (cls, alpha) in zip(share, shades, strict=False):
        w = width * pct / 100
        bar += f'<rect x="{x:.1f}" y="566" width="{max(w - 2, 1):.1f}" height="4" class="{cls}" opacity="{alpha}"/>'
        x += w

        label = f"{name} {round(pct) if pct >= 1 else '<1'}%"
        end = lx + 14 + mono_width(label, 12, .04)
        if end > 650:  # leave room for the "updated" stamp
            continue
        labels += (
            f'<rect x="{lx}" y="589" width="8" height="8" class="{cls}" opacity="{alpha}"/>'
            f'<text x="{lx + 14}" y="598" class="mono">{escape(label)}</text>'
        )
        lx = round(end + 22)

    # Whatever is left (languages past the top 5) as a faint tail.
    if x < RIGHT - 1:
        bar += f'<rect x="{x:.1f}" y="566" width="{RIGHT - x:.1f}" height="4" class="inkf" opacity=".08"/>'
    return bar + labels


def render_motes():
    """Sand grains blown across the dune (fixed seed, so the file only changes with the data)."""
    rng = random.Random(7)
    return "".join(
        f'<circle class="acc mote" cx="{rng.randint(40, 800)}" cy="{rng.randint(DUNE_Y - 70, DUNE_Y - 6)}" '
        f'r="{rng.choice([1, 1.3, 1.7])}" '
        f'style="animation-duration:{rng.uniform(5, 9):.1f}s;animation-delay:-{rng.uniform(0, 9):.1f}s"/>'
        for _ in range(18)
    )


def render_svg(data):
    gh, wx = data["github"], data["weather"]

    weather = (
        f"{wx['temperature']}  ·  {wx['condition'].lower()} in Hyderabad"
        if wx["temperature"]
        else "weather unavailable"
    )
    # Header: username, pulsing "live" dot, then the label.
    name_w = mono_width(USERNAME, 10.5, .18)
    share = gh.get("language_share") or [(lang, 0) for lang in gh["top_languages"]]
    if isinstance(share, dict):
        share = list(share.items())

    tokens = {
        "USERNAME": USERNAME,
        "USERNAME_UP": escape(USERNAME.upper()),
        "STATUS_RAW": escape(data["status"]),
        "FONTS": font_face_css(),
        "DOT_X": f"{LEFT + name_w + 10:.1f}",
        "LIVE_X": f"{LEFT + name_w + 22:.1f}",
        "MOON_X": str(MOON_X),
        "MOON_Y": str(MOON_Y),
        "BASE": str(BASE),
        "COL": str(COL),
        "DUNE_Y": str(DUNE_Y),
        "AXIS_Y": str(DUNE_Y + 20),
        "WEATHER": escape(weather),
        "CELLS": render_cells(gh),
        "LANGS": render_langs(share),
        "UPDATED": escape(data["updated"]),
        **render_status(data["status"].strip()),
        **render_push(gh),
        **render_dune(gh.get("daily_contributions_30d") or []),
    }
    tokens["DUNE"] += render_motes()

    svg = SVG_TEMPLATE
    for key, value in tokens.items():
        svg = svg.replace(f"@@{key}@@", value)
    return svg


